    }
    public function snapshot(int $actor,int $id):array {
        $row=$this->row($id);$this->visible($actor,$row);
        $out=['staff'=>$row,'leaves'=>$this->repo->run('SELECT * FROM hr_leave WHERE staff_id=? ORDER BY id DESC',[$id])->fetchAll(),'items'=>$this->repo->run('SELECT * FROM hr_items WHERE staff_id=? ORDER BY id DESC',[$id])->fetchAll(),'history'=>$this->can($actor,'hr.view')?$this->repo->run('SELECT * FROM hr_history WHERE staff_id=? ORDER BY id DESC LIMIT 200',[$id])->fetchAll():[]];
        $this->access->audit($actor,'hr.profile_viewed','staff',(string)$id,'succeeded');return $out;
    }
    private function text(array $in,string $key,int $max,bool $required=false):string {$v=$in[$key] ?? '';if(!is_string($v))throw new RuntimeException('Invalid '.$key.'.');$v=trim($v);if(($required&&$v==='')||!mb_check_encoding($v,'UTF-8')||mb_strlen($v)>$max||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]/',$v))throw new RuntimeException('Invalid or overly long '.$key.'.');return $v;}
    private function date(string $date,bool $required=true):string {if(!$required&&$date==='')return ''; $p=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$p||$p->format('Y-m-d')!==$date||$date<'1900-01-01')throw new RuntimeException('Enter a valid date.');return $date;}
    private function profile(array $in):array {$out=[];foreach(['name'=>120,'preferred'=>120,'email'=>190,'phone'=>60,'address'=>500,'dob'=>10,'job'=>120,'department'=>120,'supervisor'=>120,'employment'=>80,'start'=>10,'probation'=>10,'contact_name'=>120,'relationship'=>80,'contact_phone'=>60,'notes'=>2000] as $k=>$max)$out[$k]=$this->text($in,$k,$max,$k==='name');if($out['email']!==''&&!filter_var($out['email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid staff email.');foreach(['dob','start','probation'] as $key)$out[$key]=$this->date($out[$key],false);foreach(['contract','identity','sop','safety','training'] as $key)$out[$key]=($in[$key] ?? '')==='1';return $out;}
    private function event(?int $actor,int $id,string $action,string $reason,array $details=[]):void {$safe=HrRichText::sanitize($reason);$this->repo->run('INSERT INTO hr_history(staff_id,actor_id,action,reason_html,details) VALUES(?,?,?,?,?)',[$id,$actor,'hr.'.$action,$safe,json_encode($details,JSON_THROW_ON_ERROR)]);$metadata=array_intersect_key($details,array_flip(['from','to','user_id','leave_id','item_id','version','effective_date','changed_fields']));$this->access->audit($actor,'hr.'.$action,'staff',(string)$id,'succeeded',$metadata);}
    private function deactivate(?int $actor,int $userId):void {
        if($actor===$userId)throw new RuntimeException('You cannot deactivate your own account through HR.');
        $this->repo->run('UPDATE security_accounts SET active=0,session_version=session_version+1 WHERE user_id=?',[$userId]);
        $this->access->assertAdministratorAvailable();
        $this->repo->run('UPDATE security_password_resets SET consumed_at=UTC_TIMESTAMP() WHERE user_id=? AND consumed_at IS NULL',[$userId]);
    }
