            $fingerprint=$in;unset($fingerprint['csrf'],$fingerprint['current_password'],$fingerprint['operation_key']);ksort($fingerprint);$fingerprint=hash('sha256',$action.'|'.json_encode($fingerprint,JSON_THROW_ON_ERROR));
            return $this->access->transaction(function()use($actor,$action,$in,$sensitive,$permission,$reason,$operation,$fingerprint){
                if($action==='request_leave'&&$this->can($actor,'hr.manage')){}else $this->permit($actor,$permission);
