                    $data=$this->profile($in);$this->repo->run('INSERT INTO hr_staff(data,created_by) VALUES(?,?)',[json_encode($data,JSON_THROW_ON_ERROR),$actor]);$id=(int)$this->repo->db->lastInsertId();$this->repo->run('UPDATE hr_staff SET staff_no=? WHERE id=?',['TIV-'.str_pad((string)$id,6,'0',STR_PAD_LEFT),$id]);$this->event($actor,$id,'staff_created',$reason,['version'=>1]);
                }else{
