                    elseif($action==='return_changes'){if(!in_array($row['status'],['draft','changes_requested']))throw new RuntimeException('Only onboarding drafts can be returned.');$this->repo->run("UPDATE hr_staff SET status='changes_requested' WHERE id=?",[$id]);$this->event($actor,$id,'onboarding_returned',$reason);}
                    elseif($action==='link_user'){$this->permit($actor,'hr.link');$target=(int)($in['user_id'] ?? 0);$account=$this->repo->user($target);if($row['user_id']||!$account||($in['link_confirm'] ?? '')!=='1'||in_array($row['status'],['exited','suspended','exit_scheduled']))throw new RuntimeException('Confirm an available account and staff identity.');$this->access->assertTargetAuthority($actor,$target);if($this->repo->isAdmin($target)&&!$this->repo->isAdmin($actor))throw new PermissionDenied('Only an administrator may link an administrator account.');if($this->repo->run('SELECT id FROM hr_staff WHERE user_id=?',[$target])->fetchColumn())throw new RuntimeException('This user is already linked to another staff record.');$this->repo->run('UPDATE hr_staff SET user_id=? WHERE id=?',[$target,$id]);$this->event($actor,$id,'existing_user_linked',$reason,['user_id'=>$target]);}
