                    elseif($action==='return_item'){$item=$this->repo->run('SELECT * FROM hr_items WHERE id=? AND staff_id=? FOR UPDATE',[(int)($in['item_id'] ?? 0),$id])->fetch();if(!$item||$item['returned_at'])throw new RuntimeException('Choose an issued, unreturned item.');$this->repo->run('UPDATE hr_items SET returned_by=?,returned_at=UTC_TIMESTAMP() WHERE id=?',[$actor,$item['id']]);$this->event($actor,$id,'item_returned',$reason,['item_id'=>(int)$item['id']]);}
