    }
    public function processDueExits(?int $userId=null):int {
        $rows=$this->repo->run("SELECT id FROM hr_staff WHERE status='exit_scheduled' AND exit_at<=UTC_DATE()".($userId?' AND user_id=?':''),$userId?[$userId]:[])->fetchAll();$count=0;
